SELECT 
FROM ticket_type
WHERE scope = 'domain'
  AND business_domain_id = #{domainId}
  AND source_global_type_id = #{sourceGlobalTypeId}
LIMIT 1

SELECT MAX(sort_order)
FROM ticket_type
WHERE scope = 'domain' AND business_domain_id = #{domainId}

SELECT COUNT(DISTINCT business_domain_id)
FROM ticket_type
WHERE scope = 'domain' AND source_global_type_id = #{globalTypeId}

SELECT COUNT(*)
FROM ticket
WHERE business_domain_id = #{domainId}
  AND ticket_type_id = #{typeId}
